package com.digitalhealth.model;
import jakarta.persistence.*;
@Entity @Table(name="healthcare_centers") public class HealthcareCenter { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String name; @Column(nullable=false,columnDefinition="TEXT") private String address; private String district; private String contactNumber; @Column(columnDefinition="TEXT") private String services; private String operatingHours; private String status="ACTIVE"; public Long getId(){return id;} public void setId(Long x){id=x;} public String getName(){return name;} public void setName(String x){name=x;} public String getAddress(){return address;} public void setAddress(String x){address=x;} public String getDistrict(){return district;} public void setDistrict(String x){district=x;} public String getContactNumber(){return contactNumber;} public void setContactNumber(String x){contactNumber=x;} public String getServices(){return services;} public void setServices(String x){services=x;} public String getOperatingHours(){return operatingHours;} public void setOperatingHours(String x){operatingHours=x;} public String getStatus(){return status;} public void setStatus(String x){status=x;} }
